use vstd::prelude::*;

verus! {

fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires
        a.len() == b.len(),
    ensures
        result.len() == a.len(),
        // Pointwise: result[i] == a[i] | b[i]
        forall|i: int|
            0 <= i < result.len() ==> result[i] == (a[i] | b[i]),
{
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    let mut result = Vec::with_capacity(a.len());

    // Work with the pre-state sequences of `a` and `b` (since they are moved by into_iter()).
    let ghost sa = a@;
    let ghost sb = b@;

    let mut idx: usize = 0;

    for (x, y) in a.into_iter().zip(b.into_iter())
        invariant
            idx <= sa.len(),
            sa.len() == sb.len(),
            result@.len() == idx,
            forall|i: int|
                0 <= i < idx ==> result@[i] == (sa[i] | sb[i]),
        decreases
            sa.len() - idx,
    {
        result.push(x | y);
        idx = idx + 1;
    }

    result
}

} // verus!

